<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
$name = $block['name'] ?? '';
$get = function( $key, $fallback = '' ) { $value = get_field( 'demand_' . $key ); return '' !== $value && null !== $value && array() !== $value ? $value : $fallback; };
$id = 'nekoko-demand-' . sanitize_html_class( $block['id'] ?? wp_unique_id() );
if ( 'acf/nekoko-demand-hero' === $name ) : $label = $get( 'hero_label', 'Kategorije potražnje' ); $title = $get( 'hero_title', 'Potražnja' ); $text = $get( 'hero_text', 'Pregledajte glavne kategorije potražnje i pronađite prilike da pomognete ljudima kojima su potrebne vaše veštine i vreme.' ); $placeholder = $get( 'hero_placeholder', 'Šta tražite?' ); $category_label = $get( 'hero_category_label', 'Kategorija' ); $submit = $get( 'hero_submit', 'Pretraži' ); $url = $get( 'hero_search_url', home_url( '/napredna-pretraga/' ) ); $image = absint( $get( 'hero_image', 0 ) ); $cards = nekoko_core_demand_category_cards(); ?>
<section class="nekoko-offer-hero nekoko-demand-hero" aria-labelledby="<?php echo esc_attr( $id ); ?>-title"><div class="nekoko-offer-hero__inner"><div class="nekoko-offer-hero__intro"><p class="nekoko-offer-hero__pill"><?php echo esc_html( $label ); ?></p><h1 id="<?php echo esc_attr( $id ); ?>-title"><?php echo esc_html( $title ); ?></h1><p><?php echo esc_html( $text ); ?></p></div><div class="nekoko-offer-hero__visual"><?php echo $image ? wp_get_attachment_image( $image, 'large', false, array( 'class' => 'nekoko-offer-hero__image', 'loading' => 'eager' ) ) : '<img class="nekoko-offer-hero__image" src="' . esc_url( get_stylesheet_directory_uri() . '/assets/images/demand-hero-collage.png' ) . '" alt="Kolaž potražnje za pomoći" loading="eager">'; ?></div><form class="nekoko-offer-hero__form" action="<?php echo esc_url( $url ); ?>" method="get"><input type="search" name="q" placeholder="<?php echo esc_attr( $placeholder ); ?>"><select name="kategorija"><option value=""><?php echo esc_html( $category_label ); ?></option><?php foreach ( $cards as $card ) : ?><option value="<?php echo esc_attr( $card['term']->term_id ); ?>"><?php echo esc_html( $card['term']->name ); ?></option><?php endforeach; ?></select><input type="hidden" name="tip" value="potraznja"><button type="submit"><?php echo esc_html( $submit ); ?></button></form></div></section>
<?php elseif ( 'acf/nekoko-demand-categories' === $name ) : $title = $get( 'categories_title', 'Sve kategorije u potražnji' ); $text = $get( 'categories_text', 'Istražite glavne kategorije u potražnji i odaberite oblast u kojoj možete da pomognete.' ); $background = sanitize_hex_color( $get( 'categories_background', '#f5f2eb' ) ) ?: '#f5f2eb'; $cards = nekoko_core_demand_category_cards(); ?>
<section class="nekoko-offer-categories nekoko-demand-categories" style="--nekoko-offer-categories-background:<?php echo esc_attr( $background ); ?>" aria-labelledby="<?php echo esc_attr( $id ); ?>-title"><div class="nekoko-offer-categories__inner"><header class="nekoko-offer-categories__header"><h2 id="<?php echo esc_attr( $id ); ?>-title"><?php echo esc_html( $title ); ?></h2><p><?php echo esc_html( $text ); ?></p></header><div class="nekoko-offer-categories__grid"><?php foreach ( $cards as $card ) : $url = get_term_link( $card['term'] ); if ( is_wp_error( $url ) ) { continue; } ?><article class="nekoko-offer-categories__card"><a class="nekoko-offer-categories__card-overlay" href="<?php echo esc_url( $url ); ?>" aria-label="<?php echo esc_attr( sprintf( 'Pogledaj oglase u kategoriji %s', $card['term']->name ) ); ?>"></a><span class="nekoko-offer-categories__icon"><?php echo nekoko_core_top_offer_icon( $card['icon'] ); ?></span><h3><?php echo esc_html( $card['term']->name ); ?></h3><?php if ( $card['children'] ) : ?><div class="nekoko-offer-categories__pills"><?php foreach ( $card['children'] as $child ) : $child_url = get_term_link( $child ); if ( ! is_wp_error( $child_url ) ) : ?><a href="<?php echo esc_url( $child_url ); ?>"><?php echo esc_html( $child->name ); ?></a><?php endif; endforeach; ?></div><?php endif; ?><span class="nekoko-offer-categories__link">Pogledaj oglase <span aria-hidden="true">&rarr;</span></span></article><?php endforeach; ?></div></div></section>
<?php elseif ( 'acf/nekoko-demand-featured-category' === $name ) : $title = $get( 'featured_title', 'Pomoć i svakodnevne usluge' ); $text = $get( 'featured_text', 'Pronađite ljude kojima su potrebni vreme, veštine i podrška u svakodnevnim obavezama.' ); $icon = $get( 'featured_icon', array() ); $pills = $get( 'featured_pills', array() ); if ( ! is_array( $pills ) ) { $pills = array(); } $link = $get( 'featured_link', array() ); $url = is_array( $link ) && ! empty( $link['url'] ) ? $link['url'] : nekoko_core_page_url( 'napredna-pretraga' ); ?>
<section class="nekoko-offer-featured-category" style="--nekoko-featured-category-background:<?php echo esc_attr( sanitize_hex_color( $get( 'featured_background', '#fff' ) ) ?: '#fff' ); ?>;--nekoko-featured-category-icon:<?php echo esc_attr( sanitize_hex_color( $get( 'featured_icon_color', '#004682' ) ) ?: '#004682' ); ?>"><div class="nekoko-offer-featured-category__inner"><article class="nekoko-offer-featured-category__card"><span class="nekoko-offer-featured-category__icon"><?php echo is_array( $icon ) && ! empty( $icon['url'] ) ? '<img src="' . esc_url( $icon['url'] ) . '" alt="' . esc_attr( $icon['alt'] ?? '' ) . '">' : nekoko_core_handshake_icon(); ?></span><div class="nekoko-offer-featured-category__content"><h2><?php echo esc_html( $title ); ?></h2><p><?php echo esc_html( $text ); ?></p><?php if ( $pills ) : ?><div class="nekoko-offer-featured-category__pills"><?php foreach ( $pills as $pill ) : if ( empty( $pill['label'] ) || empty( $pill['link']['url'] ) ) { continue; } ?><a href="<?php echo esc_url( $pill['link']['url'] ); ?>"><?php echo esc_html( $pill['label'] ); ?></a><?php endforeach; ?></div><?php endif; ?></div><a class="nekoko-offer-featured-category__link" href="<?php echo esc_url( $url ); ?>"><?php echo esc_html( $get( 'featured_link_label', 'Pogledaj oglase' ) ); ?> <span aria-hidden="true">&rarr;</span></a></article></div></section>
<?php else : $title = $get( 'cta_title', 'Potrebna vam je pomoć?' ); $text = $get( 'cta_text', 'Objavite potražnju i povežite se sa ljudima koji mogu da pomognu.' ); $link = $get( 'cta_button_link', array() ); $url = is_array( $link ) && ! empty( $link['url'] ) ? $link['url'] : nekoko_core_page_url( 'postavite-oglas' ); ?>
<section class="nekoko-offer-cta-banner" style="--nekoko-offer-cta-background:<?php echo esc_attr( sanitize_hex_color( $get( 'cta_background', '#fbe9e8' ) ) ?: '#fbe9e8' ); ?>"><div class="nekoko-offer-cta-banner__inner"><div class="nekoko-offer-cta-banner__content"><h2><?php echo esc_html( $title ); ?></h2><p><?php echo esc_html( $text ); ?></p></div><a class="nekoko-offer-cta-banner__button" href="<?php echo esc_url( $url ); ?>"><?php echo esc_html( $get( 'cta_button_label', 'Objavite potražnju' ) ); ?></a><aside class="nekoko-offer-cta-banner__note"><span class="nekoko-offer-cta-banner__rays" aria-hidden="true">☀</span><strong><?php echo nl2br( esc_html( $get( 'cta_note', 'Prava pomoć može biti bliže nego što mislite' ) ) ); ?></strong><span class="nekoko-offer-cta-banner__check" aria-hidden="true">✓</span></aside></div></section>
<?php endif; ?>
